import pandas as pd


def _is_null(v):
    try:
        return bool(pd.isna(v))
    except (TypeError, ValueError):
        return v is None


def _values_equal(a, b):
    a_null = _is_null(a)
    b_null = _is_null(b)
    if a_null and b_null:
        return True
    if a_null != b_null:
        return False
    return a == b


def run(inputs: dict) -> dict:
    dim_product = inputs["DIM_PRODUCT"]
    stg_product = inputs["STG_PRODUCT"]

    cols = ["product_id", "category", "price_band",
            "eff_start_date", "eff_end_date", "is_current"]

    rows = []
    for rec in dim_product.to_dict("records"):
        rows.append({c: rec.get(c) for c in cols})

    # Map product_id -> index of its current row (is_current == 1)
    current_map = {}
    for idx, r in enumerate(rows):
        if not _is_null(r.get("is_current")) and int(r.get("is_current")) == 1:
            current_map[r["product_id"]] = idx

    # Stable sort by product_id, update_date ascending (preserves original
    # order for ties, though staged dates are unique per product per batch)
    stg_sorted = stg_product.sort_values(
        by=["product_id", "update_date"], kind="stable"
    )

    for s in stg_sorted.itertuples(index=False):
        pid = s.product_id
        s_category = s.category
        s_price_band = s.price_band
        s_update_date = s.update_date

        cur_idx = current_map.get(pid)

        if cur_idx is None:
            new_row = {
                "product_id": pid,
                "category": s_category,
                "price_band": s_price_band,
                "eff_start_date": s_update_date,
                "eff_end_date": None,
                "is_current": 1,
            }
            rows.append(new_row)
            current_map[pid] = len(rows) - 1
        else:
            c = rows[cur_idx]
            changed = (
                not _values_equal(c.get("category"), s_category)
                or not _values_equal(c.get("price_band"), s_price_band)
            )
            if changed:
                c["eff_end_date"] = s_update_date
                c["is_current"] = 0

                new_row = {
                    "product_id": pid,
                    "category": s_category,
                    "price_band": s_price_band,
                    "eff_start_date": s_update_date,
                    "eff_end_date": None,
                    "is_current": 1,
                }
                rows.append(new_row)
                current_map[pid] = len(rows) - 1
            # else: no-op, unchanged record does not create a new version

    result = pd.DataFrame(rows, columns=cols)

    return {"dim_product_out": result}
